def parse_record(record):
    if not isinstance(record, dict):
        return None
    price, qty = record.get('price'), record.get('qty')
    if isinstance(price, bool) or isinstance(qty, bool):
        return None
    if not isinstance(price, (int, float)) or not isinstance(qty, (int, float)):
        return None
    return {'price': price, 'qty': qty}


def total_and_count(records):
    total, count = 0, 0
    for record in records:
        parsed = parse_record(record)
        if parsed is None:
            continue
        total += parsed['price'] * parsed['qty']
        count += 1
    return total, count


def format_summary(total, count):
    if count == 0:
        return '无有效订单'
    return f'共 {count} 单，合计 {total:.2f} 元，均价 {total / count:.2f} 元'


def process(records):
    total, count = total_and_count(records)
    return format_summary(total, count)


data = [
    {'price': 10, 'qty': 2},
    {'price': 5.5, 'qty': 4},
    {'price': None, 'qty': 3},
    {'qty': 9},
    {'price': 3, 'qty': 1},
]
print(process(data))
print(process([]))
